#include "render/lighting.hpp"
#include <algorithm>
#include <cmath>
#include <stdexcept>
namespace kg::render {
namespace {constexpr float PI=3.14159265358979323846f;Vec3 sub(Vec3 a,Vec3 b){return {a.x-b.x,a.y-b.y,a.z-b.z};}Vec3 cross(Vec3 a,Vec3 b){return {a.y*b.z-a.z*b.y,a.z*b.x-a.x*b.z,a.x*b.y-a.y*b.x};}float sat(float x){return std::clamp(x,0.f,1.f);} Rgb add(Rgb a,Rgb b){return {a.r+b.r,a.g+b.g,a.b+b.b};} Rgb mul(Rgb a,float x){return {a.r*x,a.g*x,a.b*x};}}
bool ShadowMap::valid()const{return width>0&&height>0&&uint64_t(width)*height==depth.size();}
float dot(Vec3 a,Vec3 b){return a.x*b.x+a.y*b.y+a.z*b.z;}
Vec3 normalize(Vec3 v){float n=std::sqrt(dot(v,v));return n>1e-10f?Vec3{v.x/n,v.y/n,v.z/n}:Vec3{};}
Vec3 transformPoint(Mat4 m,Vec3 v){const auto& a=m.m;float w=a[3]*v.x+a[7]*v.y+a[11]*v.z+a[15];if(std::abs(w)<1e-8f)throw std::invalid_argument("homogeneous w is zero");return {(a[0]*v.x+a[4]*v.y+a[8]*v.z+a[12])/w,(a[1]*v.x+a[5]*v.y+a[9]*v.z+a[13])/w,(a[2]*v.x+a[6]*v.y+a[10]*v.z+a[14])/w};}
Mat4 orthographic(float l,float r,float b,float t,float n,float f){if(!(r>l&&t>b&&f>n))throw std::invalid_argument("invalid orthographic bounds");Mat4 m; m.m={2/(r-l),0,0,0, 0,2/(t-b),0,0, 0,0,1/(n-f),0, -(r+l)/(r-l),-(t+b)/(t-b),n/(n-f),1};return m;}
Mat4 lookAt(Vec3 eye,Vec3 target,Vec3 up){Vec3 z=normalize(sub(eye,target)),x=normalize(cross(up,z)),y=cross(z,x);if(dot(x,x)<.5f||dot(z,z)<.5f)throw std::invalid_argument("degenerate lookAt");Mat4 m;m.m={x.x,y.x,z.x,0,x.y,y.y,z.y,0,x.z,y.z,z.z,0,-dot(x,eye),-dot(y,eye),-dot(z,eye),1};return m;}
Cascades cascadeSplits(float n,float f,uint32_t count,float lambda){if(!(n>0&&f>n&&count>=1&&count<=8&&lambda>=0&&lambda<=1))throw std::invalid_argument("invalid cascades");Cascades out;for(uint32_t i=1;i<=count;i++){float p=float(i)/count;out.splits.push_back(lambda*(n*std::pow(f/n,p))+(1-lambda)*(n+(f-n)*p));}return out;}
uint32_t chooseCascade(float depth,const Cascades& c){if(c.splits.empty())throw std::invalid_argument("no cascades");auto it=std::lower_bound(c.splits.begin(),c.splits.end(),depth);return uint32_t(std::min<size_t>(it-c.splits.begin(),c.splits.size()-1));}
float slopeBias(Vec3 normal,Vec3 lightDirection,ShadowSettings s){return s.bias+s.normalBias*(1-sat(dot(normalize(normal),normalize(lightDirection))));}
float sampleShadowNearest(const ShadowMap& m,float u,float v,float d,float bias){if(!m.valid())throw std::invalid_argument("invalid shadow map");if(!std::isfinite(u)||!std::isfinite(v)||!std::isfinite(d))throw std::invalid_argument("nonfinite shadow sample");if(u<0||u>1||v<0||v>1||d<0||d>1)return 1.f;uint32_t x=std::min(uint32_t(u*m.width),m.width-1),y=std::min(uint32_t(v*m.height),m.height-1);return d-bias<=m.depth[size_t(y)*m.width+x]?1.f:0.f;}
float sampleShadowPcf(const ShadowMap& m,float u,float v,float d,float bias,uint32_t radius){if(!m.valid()||radius>8)throw std::invalid_argument("invalid PCF parameters");float sum=0;int r=int(radius);for(int y=-r;y<=r;y++)for(int x=-r;x<=r;x++)sum+=sampleShadowNearest(m,u+float(x)/m.width,v+float(y)/m.height,d,bias);return sum/float((2*r+1)*(2*r+1));}
float lambert(Vec3 n,Vec3 l){return sat(dot(normalize(n),normalize(l)));}
float ggxDistribution(float ndoth,float roughness){float a=std::max(.045f,roughness);a*=a;float a2=a*a;float q=ndoth*ndoth*(a2-1)+1;return a2/(PI*q*q+1e-8f);}
float smithGeometry(float ndotv,float ndotl,float roughness){float r=std::max(.045f,roughness);float k=(r+1)*(r+1)/8;auto g=[k](float v){return v/(v*(1-k)+k+1e-8f);};return g(sat(ndotv))*g(sat(ndotl));}
Rgb shadeDirectional(Rgb albedo,Vec3 normal,Vec3 viewDirection,Light sun,float roughness,float metallic,float visibility,float ambient){Vec3 n=normalize(normal),l=normalize({-sun.direction.x,-sun.direction.y,-sun.direction.z}),v=normalize(viewDirection),h=normalize({l.x+v.x,l.y+v.y,l.z+v.z});float nl=lambert(n,l),nv=lambert(n,v),vh=sat(dot(v,h));float d=ggxDistribution(sat(dot(n,h)),roughness),g=smithGeometry(nv,nl,roughness);float power=std::max(0.f,sun.intensity)*sat(visibility)*nl;float f=std::pow(1-vh,5);auto channel=[&](float base,float color){float f0=.04f*(1-sat(metallic))+base*sat(metallic);float fresnel=f0+(1-f0)*f;float spec=d*g*fresnel/(4*nv*nl+1e-5f);float diff=(1-sat(metallic))*(1-fresnel)*base/PI;return std::max(0.f,base*std::max(0.f,ambient)+power*color*(diff+spec));};return {channel(albedo.r,sun.color.r),channel(albedo.g,sun.color.g),channel(albedo.b,sun.color.b)};}
Rgb shadePoint(Rgb albedo,Vec3 p,Vec3 n,PointLight light){Vec3 delta=sub(light.position,p);float dist2=dot(delta,delta);float dist=std::sqrt(dist2);if(light.range<=0||dist>=light.range)return {};float attenuation=std::pow(sat(1-dist/light.range),2)/(1+dist2);float power=std::max(0.f,light.intensity)*attenuation*lambert(n,delta);return {albedo.r*light.color.r*power,albedo.g*light.color.g*power,albedo.b*light.color.b*power};}
bool validateShadowSettings(const ShadowSettings& s,std::string* error){bool ok=std::isfinite(s.bias)&&s.bias>=0&&s.bias<=.1f&&std::isfinite(s.normalBias)&&s.normalBias>=0&&s.normalBias<=.1f&&s.pcfRadius<=8&&std::isfinite(s.cascadeLambda)&&s.cascadeLambda>=0&&s.cascadeLambda<=1;if(!ok&&error)*error="invalid shadow settings";return ok;}
}
